}

Method.Source:
/// <summary>
/// Created for the FSD - CB201, Rebates Extension - Undertake Build -  External Data Sources
/// </summary>
/// <param name="sender">FormDataObject</param>
/// <param name="eFormDataFieldEventArgsparam>
[FormDataFieldEventHandler(formDataFieldStr(GUPPriceRebatePriceAttributeGroupEdit, TAMRebateTable, PriceComponentCombination), FormDataFieldEventType::Modified)]
public static void PriceComponentCombination_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource  rebateTable_ds   = sender.datasource();
    TAMRebateTable  rebateTable      = rebateTable_ds.cursor();
    TAMRebateDeal   rebateDeal;

    select firstonly METUseExternalSellData from rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal;

    if (rebateDeal.METUseExternalSellData == NoYes::Yes && rebateTable.PriceComponentCombination)
    {
        GUPPricingAttributeLink                             priceAttributeLink;
        GUPPriceComponentCodePriceAttributeGroupCombination priceAtrributeGroupCombination;

        priceAtrributeGroupCombination =  GUPPriceComponentCodePriceAttributeGroupCombination::find(rebateTable.PriceComponentCombination);

        select firstonly RecId from priceAttributeLink
            where priceAttributeLink.PriceAttributeGroupName == priceAtrributeGroupCombination.HeaderPriceAttributeGroupName
            && (priceAttributeLink.TableName == tableStr(SalesTable) || priceAttributeLink.TableName == tableStr(SalesLine));

        if (priceAttributeLink.RecId)
        {
            throw warning("@MET:UseExtDataSOError");
        }
    }
}
